head.script:
// 화면 리사이징

scwin.pSndNo;
scwin.pMktCd;
scwin.pSndlocCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.pSndNo = $c.frame.path("../").scwin.pSndNo;
        scwin.pMktCd = $c.frame.path("../").scwin.pMktCd;
        scwin.pSndlocCd = $c.frame.path("../").scwin.pSndlocCd;
        await scwin.search(scwin.pSndNo, scwin.pMktCd, scwin.pSndlocCd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35006_POP.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_list_OnLoadCompleted
 * @description dts_list 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_list_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_list.errorMsg) {
            await $c.win.alert("조회할 수 없습니다. 시스템 관리자에게 문의하세요");
        } else {
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35006_POP.dts_list_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_list_OnLoadError
 * @description dts_list 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_list_OnLoadError = async function() {
    try {
        await $c.win.alert("조회할 수 없습니다. 시스템 관리자에게 문의하세요");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35006_POP.dts_list_OnLoadError" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35006_POP.img_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 그리드의 데이타 조회
 * @param {*} sndno sndno
 * @param {*} mktcd mktcd
 * @param {*} sndcd sndcd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function(sndno, mktcd, sndcd) {

    // 그리드의 데이타 조회
    const sbmOptions = {
        id : "sbm_dts_list",
        action : "/AtsContactInfo.do",
        ref : "",
        target : "dts_list=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
